/bin/bash -lc "git status --short
git diff --check
python3 - <<'PY'
from tally import allocate, duration, fields, intervals, ledger
from fractions import Fraction
assert allocate.share_out(-7, [0,Fraction(1,3),Fraction(1,3)]) == [0,-4,-3]
assert allocate.share_out(5, [1e308,1e308]) == [3,2]
assert ledger.bill([(' A','15m'),('b','15m'),('a','0s')],1)==[('A',1),('b',0)]
assert ledger.bill([('Z','0s'),('x','0m')],10)==[('Z',0),('x',0)]
assert fields.parse_fields(\" | a=' p''|q= ' ||b= |\")=={'a':\" p'|q= \",'b':''}
for inp in [\"a='oops\", \"a=1| a=2\", '=2','missing']:
    try: fields.parse_fields(inp)
    except ValueError: pass
    else: raise AssertionError(inp)
assert intervals.free_slots([(14,20),(-1,4),(8,9),(4,5)],0,18,3)==[(5,8),(9,14)]
assert duration.parse(' 2D 5m ')==173100
for inp in ['','   ','1m2h','1d1D','1s"'!'"','1 h']:
    try: duration.parse(inp)
    except ValueError: pass
    else: raise AssertionError(inp)
print('Helper edge cases passed')
PY"

